CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, display_name text NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'member', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tasks (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), objective text NOT NULL, status text NOT NULL, period_days integer NOT NULL DEFAULT 30, result jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS opportunities (id uuid PRIMARY KEY, account text NOT NULL, name text NOT NULL, stage text NOT NULL, amount numeric(14,2) NOT NULL, owner text NOT NULL, last_contact_at timestamptz, expected_close_at timestamptz, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS revenue_records (id uuid PRIMARY KEY, period_start date NOT NULL, revenue numeric(14,2) NOT NULL, source text NOT NULL DEFAULT 'sample', UNIQUE(period_start, source));
CREATE TABLE IF NOT EXISTS tool_invocations (id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, tool_id text NOT NULL, input jsonb NOT NULL, output jsonb, status text NOT NULL, started_at timestamptz NOT NULL, completed_at timestamptz, error jsonb);
CREATE TABLE IF NOT EXISTS proposed_actions (id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, action_type text NOT NULL, target_id uuid REFERENCES opportunities(id), parameters jsonb NOT NULL, action_hash text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approval_requests (id uuid PRIMARY KEY, action_id uuid NOT NULL UNIQUE REFERENCES proposed_actions(id), action_hash text NOT NULL, status text NOT NULL, reviewer_id uuid REFERENCES users(id), rationale text, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS executions (id uuid PRIMARY KEY, action_id uuid NOT NULL REFERENCES proposed_actions(id), status text NOT NULL, request jsonb NOT NULL, response jsonb, started_at timestamptz NOT NULL, completed_at timestamptz, UNIQUE(action_id));
CREATE TABLE IF NOT EXISTS verification_results (id uuid PRIMARY KEY, execution_id uuid NOT NULL UNIQUE REFERENCES executions(id), status text NOT NULL, criteria jsonb NOT NULL, evidence jsonb NOT NULL DEFAULT '[]'::jsonb, checked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_stages (id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, stage_number integer NOT NULL, name text NOT NULL, status text NOT NULL, details jsonb NOT NULL DEFAULT '{}'::jsonb, started_at timestamptz, completed_at timestamptz, UNIQUE(task_id, stage_number));
CREATE TABLE IF NOT EXISTS evidence (id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, source text NOT NULL, reference_id text, summary text NOT NULL, facts jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS flight_recorder_events (id uuid PRIMARY KEY, task_id uuid REFERENCES tasks(id) ON DELETE CASCADE, event_type text NOT NULL, status text NOT NULL, payload jsonb NOT NULL, previous_hash text NOT NULL, integrity_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL, title text NOT NULL, body text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS profiles (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, data jsonb NOT NULL DEFAULT '{}'::jsonb, privacy jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS friendship_requests (id uuid PRIMARY KEY, from_user_id uuid NOT NULL REFERENCES users(id), to_user_id uuid NOT NULL REFERENCES users(id), status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(from_user_id, to_user_id));
CREATE TABLE IF NOT EXISTS communities (id uuid PRIMARY KEY, name text NOT NULL, description text NOT NULL, member_count integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS community_memberships (user_id uuid NOT NULL REFERENCES users(id), community_id uuid NOT NULL REFERENCES communities(id), joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id, community_id));
CREATE TABLE IF NOT EXISTS conversations (id uuid PRIMARY KEY, participant_ids uuid[] NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id uuid PRIMARY KEY, conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS system_state (id smallint PRIMARY KEY CHECK (id = 1), state_json jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS tasks_user_created_idx ON tasks(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS opportunities_status_contact_idx ON opportunities(status, last_contact_at);
CREATE INDEX IF NOT EXISTS recorder_task_created_idx ON flight_recorder_events(task_id, created_at);
CREATE INDEX IF NOT EXISTS invocations_task_started_idx ON tool_invocations(task_id, started_at);
CREATE INDEX IF NOT EXISTS messages_conversation_created_idx ON messages(conversation_id, created_at);
